python
def parcelBudgetFloorTicket(drawers, k):
    a=drawers
    out=[]
    dp=[0]*(k+1)
    for weight,value in a:
        for c in range(k,weight-1,-1): dp[c]=max(dp[c],dp[c-weight]+value)
    out=dp
    return min(out,default=0)


java
class Solution {
  public int parcelBudgetFloorTicket(int[][] drawers, int k) {
    int[][] a=drawers; List<Integer> out=new ArrayList<>();
    {int[]dp=new int[k+1];for(int[]item:a)for(int c=k;c>=item[0];c--)dp[c]=Math.max(dp[c],dp[c-item[0]]+item[1]);for(int x:dp)out.add(x);}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.min(answer,x);return answer;
  }
}
